import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import { isMattPocockImplement, parseLinkedIssue } from './detect'

const offerRef = { plugin: 'dusky-implement', key: 'offer' } as const
const offer = atom(offerRef, null)

// O --prefill chega à caixa de prompt logo depois do início da sessão: lê a caixa por
// alguns segundos. Fora dessa janela, um texto igual digitado depois não conta.
const POLL_MS = 250
const POLL_TRIES = 24

async function findImplementSkill($: EngineInterface, cwd: string): Promise<boolean> {
  let root = cwd
  try {
    const git = await $.process.run(['git', 'rev-parse', '--show-toplevel'], { cwd, timeoutMs: 5000 })
    if (git.exitCode === 0 && git.stdout.trim()) root = git.stdout.trim()
  } catch {
    // fora de um repo git: fica o cwd
  }

  for (const dir of new Set([cwd, root])) {
    const skillPath = `${dir}/.claude/skills/implement/SKILL.md`
    if (!(await $.fs.exists(skillPath))) continue

    const skillText = await $.fs.read(skillPath)
    const lockPath = `${dir}/skills-lock.json`
    const lockText = (await $.fs.exists(lockPath)) ? await $.fs.read(lockPath) : null
    if (isMattPocockImplement(lockText, skillText)) return true
  }

  return false
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    const result = await next(e)
    if (!e.isInteractive) return result

    // Um reload do mod roda session.start de novo: não reabre uma oferta já usada ou dispensada.
    const known = await $.state.get(offerRef)
    if (known.version !== undefined && known.version > 0) return result

    if (!(await findImplementSkill($, e.cwd))) return result

    let tries = 0
    const poll = $.clock.every(POLL_MS, async () => {
      tries += 1
      const found = parseLinkedIssue((await $.prompt.read()).text)
      if (found) {
        poll.cancel()
        await update($, offer, () => found)
      } else if (tries >= POLL_TRIES) {
        poll.cancel()
      }
    })

    return result
  })

  // O rascunho enviado à mão (ou qualquer outro prompt) encerra a oferta.
  on('prompt.submit', async ($, e, next) => {
    if (e.origin.kind === 'composer' && (await read($, offer)) !== null) {
      await update($, offer, () => null)
    }
    return next(e)
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const current = await read($, offer)
    if (current === null || e.props.hasSurvey || e.props.isWorking || e.props.view.agentId) {
      return next(e)
    }

    const { Box, Button, Text } = $.ui.resolve(e)

    const implement = async () => {
      const box = await $.prompt.read()
      // O que a pessoa acrescentou ao rascunho vai junto; se ela apagou o bloco, vale o original.
      const draft = parseLinkedIssue(box.text) ? box.text.trim() : current.draft
      await update($, offer, () => null)
      await $.prompt.fill({ text: '' })
      await $.command.run({ command: 'implement', args: draft })
    }

    return (
      <Box flexDirection="row" gap={1}>
        <Text dimColor>
          It's a Plan {current.identifier ?? 'issue'} · skill implement disponível
        </Text>
        <Button key="implement" label="Implementar" variant="primary" hotkey="i" onPress={implement} />
        <Button key="dismiss" label="Dispensar" role="dismiss" onPress={() => update($, offer, () => null)} />
      </Box>
    )
  })
}

