import type { ImplementOffer } from '../types'

// O bloco que o Dusky escreve em `claude --prefill` ao iniciar uma issue num worktree novo,
// com o ID e a URL da issue em questão (a URL pode vir recuada):
//   Linked It's a Plan issue: <ID_DA_ISSUE>
//     http://localhost:43101/jm/issue/<ID_DA_ISSUE>
const LINKED_BLOCK =
  /^[ \t]*Linked It['’]s a Plan issue(?::[ \t]*(\S+))?[ \t]*\r?\n[ \t]*(https?:\/\/\S+)/m
const ISSUE_IN_URL = /\/issue\/([^/?#\s]+)/

export function parseLinkedIssue(text: string): ImplementOffer | null {
  const match = LINKED_BLOCK.exec(text)
  if (!match) return null

  const url = match[2] ?? ''
  const identifier = match[1] ?? ISSUE_IN_URL.exec(url)?.[1] ?? null

  return { identifier, url, draft: match[0].trim() }
}

const MATT_SOURCE = /^mattpocock\/skills$/i
const MATT_DESCRIPTION = /Implement a piece of work based on a spec or set of tickets/i

// A skill é a do Matt Pocock quando o skills-lock.json do repo a atribui a `mattpocock/skills`;
// sem lock, vale a assinatura do SKILL.md publicado em mattpocock/skills.
export function isMattPocockImplement(lockText: string | null, skillText: string): boolean {
  if (lockText !== null) {
    try {
      const source = JSON.parse(lockText)?.skills?.implement?.source
      if (typeof source === 'string') return MATT_SOURCE.test(source)
    } catch {
      // lock ilegível: decide pelo SKILL.md
    }
  }

  return /^name:\s*["']?implement["']?\s*$/m.test(skillText) && MATT_DESCRIPTION.test(skillText)
}

