export type ImplementOffer = {
  /** `DSK-24`, quando o rascunho ou a URL o trazem. */
  identifier: string | null
  url: string
  /** O bloco do rascunho como o Dusky o escreveu. */
  draft: string
}

declare module 'claude-code' {
  interface PluginState {
    'dusky-implement': { offer: ImplementOffer | null }
  }
}
